#!/bin/bash
# Centre colour of glass by size, and the shadow round it.
HERE="$(cd "$(dirname "$0")/.." && pwd)"; cd "$HERE"; R=.build/r; w(){ perl -e "select(undef,undef,undef,$1)"; }
for mode in dark light; do ./run.sh appearance $mode; for sz in "44 44 22" "100 36 18" "100 44 22" "110 52 26" "200 60 30" "200 80 30" "300 90 28" "300 120 28" "300 200 28" "390 400 28"; do set -- $sz; o="$mode ${1}x$2:"; for bg in 000000 404040 808080 c0c0c0 ffffff; do ./run.sh do launch -engine native -kind regular -w $1 -h $2 -r $3 -bg $bg; w 1.2; ./run.sh snap x $R/q.png; o="$o $(.build/sample $R/q.png mean 600 897 6 6 | cut -d' ' -f1)"; done; echo "$o"; done; done
./run.sh appearance light; for sz in "100 36 18" "110 52 26" "200 80 30" "300 120 28"; do set -- $sz; ./run.sh do launch -engine native -kind regular -w $1 -h $2 -r $3 -bg ffffff; w 1.4; ./run.sh snap x $R/q.png; top=$((900-$2*3/2)); bot=$((900+$2*3/2)); left=$((603-$1*3/2)); echo "shadow $1x$2  below: $(.build/sample $R/q.png col 603 $((bot+2)) $((bot+70)) | awk 'NR%8==1{printf "%s ",$2}')   above: $(.build/sample $R/q.png col 603 $((top-40)) $((top-3)) | awk 'NR%8==1{printf "%s ",$2}')  side: $(.build/sample $R/q.png row 900 $((left-50)) $((left-3)) | awk 'NR%8==1{printf "%s ",$2}')"; done
./run.sh do launch -engine native -scene controls -bg 808080; w 1.5; ./run.sh snap x $R/q2.png; echo "STEPPER row $(.build/sample $R/q2.png row 512 500 720 | awk 'NR%6==1{printf "%s ",$2}')"; ./run.sh do launch -engine web -scene controls -bg 808080; w 2; ./run.sh snap x $R/q3.png; echo "WEB row $(.build/sample $R/q3.png row 512 500 720 | awk 'NR%6==1{printf "%s ",$2}')"
